    """Find all non-overlapping placements of the 3-cell motif."""
    h, w = len(grid), len(grid[0])
    pattern = ((0, 0), (0, 1), (1, 2))
    matches = []
    for r in range(h - 1):
        for c in range(w - 2):
            cells = [(r + dr, c + dc) for dr, dc in pattern]
            if all(grid[x][y] in (0, 8) for x, y in cells):
                matches.append((r, c, cells))

    # Demonstration markings are a seed subset. Select the maximum-size
    # compatible set of placements, requiring every seeded 8 to be covered.
    by_cell = {}
    for idx, (_, _, cells) in enumerate(matches):
        for cell in cells:
            by_cell.setdefault(cell, []).append(idx)
    seeds = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    best = []
    def search(chosen, occupied, remaining):
        nonlocal best
        if len(chosen) + len(remaining) < len(best):
            return
        uncovered = [cell for cell in seeds if cell not in occupied]
        if uncovered:
            cell = min(uncovered, key=lambda q: sum(i in remaining for i in by_cell.get(q, [])))
            options = [i for i in by_cell.get(cell, []) if i in remaining and not (set(matches[i][2]) & occupied)]
            if not options:
                return
        else:
            if len(chosen) > len(best): best = chosen[:]
            options = [i for i in remaining if not (set(matches[i][2]) & occupied)]
            if not options: return
        for i in options:
            cells = set(matches[i][2])
            search(chosen + [i], occupied | cells, remaining - {i})
    search([], set(), set(range(len(matches))))

    out = [row[:] for row in grid]
    for i in best:
        for r, c in matches[i][2]:
            out[r][c] = 8
    return out
